import { isMint } from './assets';

// Accept only the ownership statement generated by this installed Privy SDK.
// A provider challenge must never become an arbitrary message-signing endpoint.
export function verifyProviderWalletMessage(message: string, wallet: string, origin: string, now = Date.now()) {
  const site = new URL(origin);
  if (!isMint(wallet) || site.origin !== origin || typeof message !== 'string' || message.length > 2048) throw Error('Invalid wallet verification message.');
  const fields = message.split('\n');
  const nonce = fields[8]?.slice('Nonce: '.length);
  const issued = fields[9]?.slice('Issued At: '.length);
  if (!nonce || !/^[A-Za-z0-9]{8,128}$/.test(nonce) || !issued || !Number.isFinite(Date.parse(issued)) || Date.parse(issued) > now + 5000 || now - Date.parse(issued) > 300000) throw Error('Wallet verification expired or changed.');
  const expected = `${site.host} wants you to sign in with your Solana account:\n${wallet}\n\nYou are proving you own ${wallet}.\n\nURI: ${origin}\nVersion: 1\nChain ID: mainnet\nNonce: ${nonce}\nIssued At: ${issued}\nResources:\n- https://privy.io`;
  if (message !== expected) throw Error('Wallet verification belongs to a different account or website.');
}
